import{_ as r,C as n,o as e,c as s,a2 as o,b as l,w as t,a as c,E as d,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const I=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_4.md"}'),p={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_4.md"};function m(g,a,h,f,b,_){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-presupuesto-cronograma-y-fundamentacion-legal" tabindex="-1">Eje Temático: Presupuesto, Cronograma y Fundamentación Legal <a class="header-anchor" href="#eje-tematico-presupuesto-cronograma-y-fundamentacion-legal" aria-label="Permalink to &quot;Eje Temático: Presupuesto, Cronograma y Fundamentación Legal&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-viabilidad-del-proyecto" tabindex="-1">🧭 Introducción: La Viabilidad del Proyecto <a class="header-anchor" href="#🧭-introduccion-la-viabilidad-del-proyecto" aria-label="Permalink to &quot;🧭 Introducción: La Viabilidad del Proyecto&quot;">​</a></h2><p>Un proyecto que tiene objetivos hermosos y actividades bien pensadas, pero que no tiene tiempo ni dinero calculado, es simplemente una carta a San Nicolás. En esta última fase de la formulación, debemos responder dos preguntas críticas que cualquier ente evaluador (o inversor) te hará: <strong>¿Cuánto cuesta?</strong> y <strong>¿Cuándo estará listo?</strong></p><p>Además, en el ejercicio profesional de la informática en Venezuela, toda acción debe estar respaldada por un marco legal vigente.</p><hr><h2 id="🏛️-capitulo-i-el-presupuesto-¿cuanto-cuesta" tabindex="-1">🏛️ CAPÍTULO I: El Presupuesto (¿Cuánto cuesta?) <a class="header-anchor" href="#🏛️-capitulo-i-el-presupuesto-¿cuanto-cuesta" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Presupuesto (¿Cuánto cuesta?)&quot;">​</a></h2><p>El presupuesto es la cuantificación económica de los recursos materiales y técnicos que definiste en la evaluación anterior.</p><h3 id="_1-1-estructura-de-costos" tabindex="-1">1.1 Estructura de Costos <a class="header-anchor" href="#_1-1-estructura-de-costos" aria-label="Permalink to &quot;1.1 Estructura de Costos&quot;">​</a></h3><p>Incluso si tu proyecto es &quot;gratuito&quot; para la comunidad (porque tú pones la mano de obra sin cobrar), el proyecto <strong>sí tiene un costo real</strong>. Si tú gastas pasajes, compras pasta térmica o pagas por impresiones, eso debe estar reflejado.</p><ul><li><strong>Costos Directos:</strong> Materiales consumibles (pasta térmica, alcohol isopropílico, tirro de embalar), impresión de manuales, alquiler de equipos (si alquilas un video beam).</li><li><strong>Costos Indirectos (Opcional pero recomendado):</strong> Transporte, refrigerios para el equipo investigador durante los días de campo.</li></ul><h3 id="_1-2-la-matriz-presupuestaria" tabindex="-1">1.2 La Matriz Presupuestaria <a class="header-anchor" href="#_1-2-la-matriz-presupuestaria" aria-label="Permalink to &quot;1.2 La Matriz Presupuestaria&quot;">​</a></h3><p>En tu informe, presentarás una tabla con: Ítem, Cantidad, Costo Unitario y Costo Total. Esto demuestra rigor técnico. Si alguna institución decide financiar el proyecto, esta tabla es su principal requisito.</p><hr><h2 id="🧩-capitulo-ii-el-cronograma-de-actividades-¿cuando" tabindex="-1">🧩 CAPÍTULO II: El Cronograma de Actividades (¿Cuándo?) <a class="header-anchor" href="#🧩-capitulo-ii-el-cronograma-de-actividades-¿cuando" aria-label="Permalink to &quot;🧩 CAPÍTULO II: El Cronograma de Actividades (¿Cuándo?)&quot;">​</a></h2><p>El tiempo es el recurso más valioso de un proyecto informático. No puedes reparar equipos y dictar talleres eternamente. Tienes fechas de corte institucionales y comunitarias.</p><h3 id="_2-1-el-diagrama-de-gantt" tabindex="-1">2.1 El Diagrama de Gantt <a class="header-anchor" href="#_2-1-el-diagrama-de-gantt" aria-label="Permalink to &quot;2.1 El Diagrama de Gantt&quot;">​</a></h3><p>La herramienta mundial por excelencia para planificar el tiempo es el Diagrama de Gantt. Es un gráfico de barras horizontales donde:</p><ul><li>El <strong>Eje Vertical (Y)</strong> lista cronológicamente todas las actividades de tu EAP.</li><li>El <strong>Eje Horizontal (X)</strong> representa el tiempo (semanas o meses).</li></ul><h3 id="_2-2-dependencias-logicas" tabindex="-1">2.2 Dependencias Lógicas <a class="header-anchor" href="#_2-2-dependencias-logicas" aria-label="Permalink to &quot;2.2 Dependencias Lógicas&quot;">​</a></h3><p>Al hacer tu Gantt, debes respetar la lógica de la informática. <em>Ejemplo:</em> No puedes &quot;Instalar el sistema operativo&quot; en la Semana 2, si la &quot;Reparación de la fuente de poder&quot; está pautada para la Semana 3. Una actividad depende de que la anterior finalice con éxito.</p><h3 id="_2-3-representacion-visual-del-gantt" tabindex="-1">2.3 Representación Visual del Gantt <a class="header-anchor" href="#_2-3-representacion-visual-del-gantt" aria-label="Permalink to &quot;2.3 Representación Visual del Gantt&quot;">​</a></h3>',24)),(e(),l(u,null,{default:t(()=>[d(i,{id:"mermaid-84",class:"mermaid",graph:"gantt%0A%20%20%20%20title%20Cronograma%20de%20Ejecuci%C3%B3n%20del%20Proyecto%0A%20%20%20%20dateFormat%20%20YYYY-MM-DD%0A%20%20%20%20axisFormat%20%20%25W%0A%20%20%20%20%0A%20%20%20%20section%20FASE%20I%3A%20Hardware%0A%20%20%20%20Limpieza%20F%C3%ADsica%20%20%20%20%20%20%20%20%20%20%20%3Aa1%2C%202026-10-01%2C%207d%0A%20%20%20%20Reemplazo%20de%20Fuentes%20%20%20%20%20%20%3Aa2%2C%20after%20a1%2C%205d%0A%20%20%20%20%0A%20%20%20%20section%20FASE%20II%3A%20Software%0A%20%20%20%20Instalaci%C3%B3n%20SO%20Linux%20%20%20%20%20%20%3Ab1%2C%20after%20a2%2C%207d%0A%20%20%20%20Configuraci%C3%B3n%20de%20Red%20Local%3Ab2%2C%20after%20b1%2C%204d%0A%20%20%20%20%0A%20%20%20%20section%20FASE%20III%3A%20Socializaci%C3%B3n%0A%20%20%20%20Taller%20de%20Ofim%C3%A1tica%20%20%20%20%20%20%20%3Ac1%2C%20after%20b1%2C%203d%0A%20%20%20%20Entrega%20Final%20a%20Comunidad%20%3Ac2%2C%20after%20b2%2C%202d%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<hr><h2 id="🏗️-capitulo-iii-fundamentacion-legal" tabindex="-1">🏗️ CAPÍTULO III: Fundamentación Legal <a class="header-anchor" href="#🏗️-capitulo-iii-fundamentacion-legal" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Fundamentación Legal&quot;">​</a></h2><p>En Venezuela, el uso de las Tecnologías de la Información (TIC) en proyectos comunitarios está fuertemente legislado. Tu proyecto (y tu informe) debe justificar legalmente por qué estás haciendo lo que estás haciendo.</p><p>Las normativas primordiales a invocar en tu informe son:</p><ol><li><strong>Constitución de la República Bolivariana de Venezuela:</strong> (Art. 110) Que reconoce el interés público de la ciencia, la tecnología y la innovación para el desarrollo económico y social.</li><li><strong>Ley de Infogobierno:</strong> Fundamental si estás instalando software en instituciones del Estado. Esta ley promueve y obliga el uso de <strong>Software Libre</strong> en la administración pública.</li><li><strong>Plan de la Patria:</strong> Vincular el proyecto con los grandes objetivos históricos de soberanía tecnológica.</li><li><strong>Reglamento del PSI/T de la UPTT:</strong> Que te otorga la autoridad y el deber académico de realizar la vinculación social.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>El Fin de la Planificación</strong> ¡Felicidades! Al finalizar esta evaluación, has completado la fase más dura intelectualmente: <strong>El Diseño del Proyecto</strong>. Tienes los objetivos, las actividades, el presupuesto, el cronograma y la ley de tu lado. En el Trimestre III (I-III) dejarás el papel y llevarás toda esta teoría al mundo real: es hora de ejecutar.</p></div>',6))])}const A=r(p,[["render",m]]);export{I as __pageData,A as default};
